const [notes, setNotes] = useState([
  { id: 1, title: 'Nota de reunión', unread: true },
  { id: 2, title: 'Ajustes guardados', unread: false },
]);
const open = () => {};
const remove = (id: number) => setNotes((all) => all.filter((note) => note.id !== id));

<ul role="list">
  {notes.map((note) => (
    <NotificationCard
      key={note.id}
      title={note.title}
      unread={note.unread}
      onClick={open}
      onDelete={() => remove(note.id)}
    />
  ))}
</ul>
